input.script:
var articles = [];
var newsItems = document.querySelectorAll('[data-testid="anchor"]');
newsItems.forEach(function(item) {
  var heading = item.querySelector('h2');
  var time = item.querySelector('time');
  var label = item.querySelector('[data-testid="card-metadata-tag"]');
  if (heading) {
    articles.push({
      title: heading.textContent.trim(),
      time: time ? time.textContent.trim() : '',
      label: label ? label.textContent.trim() : ''
    });
  }
});
return articles;

var articles = [];
var newsItems = document.querySelectorAll('h2[data-testid="card-headline"]');
newsItems.forEach(function(item) {
  var container = item.closest('[data-testid="dundee-article"]') || item.closest('[data-testid="internal-link"]');
  var time = null;
  var label = null;
  var description = '';
  if (container) {
    var timeEl = container.querySelector('[data-testid="card-metadata-lastupdated"]');
    var labelEl = container.querySelector('[data-testid="card-metadata-tag"]');
    var descEl = container.querySelector('p[data-testid="card-description"]');
    if (timeEl) time = timeEl.textContent.trim();
    if (labelEl) label = labelEl.textContent.trim();
    if (descEl) description = descEl.textContent.trim();
  }
  articles.push({
    title: item.textContent.trim(),
    time: time,
    label: label,
    description: description
  });
});
return articles;

var articles = [];
var links = document.querySelectorAll('a[data-testid="internal-link"]');
links.forEach(function(link) {
  var text = link.textContent.trim();
  // Find tech-related articles
  if (text.includes('AI') || text.includes('algorithm') || text.includes('OpenAI') || text.includes('tech') || text.includes('dopamine') || text.includes('shopping without paying')) {
    var parent = link.closest('[data-testid="dundee-article"]');
    if (!parent) parent = link.parentElement;
    var timeEl = link.querySelector('[data-testid="card-metadata-lastupdated"]') || (parent && parent.querySelector('[data-testid="card-metadata-lastupdated"]'));
    var headline = link.querySelector('h2');
    articles.push({
      title: headline ? headline.textContent.trim() : text.substring(0, 100),
      time: timeEl ? timeEl.textContent.trim() : 'no time found',
      href: link.href
    });
  }
});
return articles;

// Fetch each technology article to check its date
var urls = [
  'https://www.bbc.com/news/articles/cwn741v5rdpxo',  // Indians shopping without paying
  'https://www.bbc.com/news/articles/cqj3dgy8x3vro',  // Australia algorithm
  'https://www.bbc.com/news/articles/c6gqdgg8w59xo',  // AI race
  'https://www.bbc.com/news/articles/cr3eqk15ld14o'   // OpenAI hack
];
return Promise.all(urls.map(function(url) {
  return fetch(url).then(function(r) { return r.text(); }).then(function(html) {
    var match = html.match(/datePublished[^"]*"([^"]+)"/);
    var timeMatch = html.match(/<time[^>]*datetime="([^"]+)"[^>]*>([^<]+)</);
    return {url: url, datePublished: match ? match[1] : 'not found', timeText: timeMatch ? timeMatch[2] : 'not found'};
  }).catch(function(e) {
    return {url: url, error: e.message};
  });
}));

var links = document.querySelectorAll('a[data-testid="internal-link"]');
var result = null;
links.forEach(function(link) {
  var headline = link.querySelector('h2');
  if (headline && headline.textContent.includes('Young people in China')) {
    result = {url: link.href, title: headline.textContent.trim()};
  }
});
return result;

var articles = [];
var links = document.querySelectorAll('a[data-testid="internal-link"]');
links.forEach(function(link) {
  var headline = link.querySelector('h2');
  var lastUpdated = link.querySelector('[data-testid="card-metadata-lastupdated"]');
  var category = link.querySelector('[data-testid="card-metadata-tag"]');
  if (headline) {
    articles.push({
      title: headline.textContent.trim(),
      time: lastUpdated ? lastUpdated.textContent.trim() : 'N/A',
      category: category ? category.textContent.trim() : 'N/A',
      href: link.href
    });
  }
});
return articles;

var article = document.querySelector('article');
if (!article) article = document.querySelector('main');
if (!article) article = document.body;
var paragraphs = article.querySelectorAll('p');
var content = [];
paragraphs.forEach(function(p) {
  var text = p.textContent.trim();
  if (text && text.length > 30) {
    content.push(text);
  }
});
return content.slice(0, 20);

// Get all headlines with their full text and dates from the Asia section page
var articles = [];
var cards = document.querySelectorAll('[data-testid="dundee-article"]');
cards.forEach(function(card) {
  var headline = card.querySelector('h2[data-testid="card-headline"]');
  var description = card.querySelector('p[data-testid="card-description"]');
  var lastUpdated = card.querySelector('[data-testid="card-metadata-lastupdated"]');
  if (headline) {
    articles.push({
      title: headline.textContent.trim(),
      description: description ? description.textContent.trim() : 'N/A',
      lastUpdated: lastUpdated ? lastUpdated.textContent.trim() : 'N/A'
    });
  }
});
return articles;
